window.deepArticles = window.deepArticles || {};

const indianIndustrySources = [
  {href:"../settingBible%20-%20AltWWII.md",label:"Setting Bible — India, Siberia, and postwar military industry"},
  {href:"../settingTimeline%20-%20AltWWII.md",label:"Setting Timeline — Soviet collapse and Indian conflict chronology"},
  {href:"../transcript.md",label:"Master Transcript — Soviet industrial diaspora and Indian design genealogies"},
  {href:"../coProsperitySphereReference%20-%20AltWWII.md",label:"Greater East Asia reference — Indian successor system"},
  {href:"../landArmamentsReference%20-%20AltWWII.md",label:"Land Armaments Reference — vehicle lineages and doctrine"}
];

const diasporaDiagram = {src:"assets/diagrams/soviet-industrial-diaspora.svg",alt:"Diagram of the two-stage Soviet military-industrial diaspora from the collapsing west to Siberian refuges and Indian successor states",caption:"Archive reconstruction · two-stage military-industrial diaspora"};
const genealogyDiagram = {src:"assets/diagrams/indian-armored-genealogies.svg",alt:"Diagram of Soviet armored-design genealogies divided among Indian successor states",caption:"Archive reconstruction · principal Indian armored genealogies"};
const vijayaDiagram = {src:"assets/diagrams/vijaya-development.svg",alt:"Diagram of Russian technical inheritance transformed into the Indian Vijaya armored family",caption:"Archive reconstruction · Vijaya development lineage"};

const indianIndustryArticle = config => ({
  category:"Technology",
  eyebrow:"Military industry · post-Soviet India",
  infoboxKicker:"Indian military-industrial history",
  ...config,
  sources:[...indianIndustrySources,...(config.primarySources || [])],
  categories:config.categories || ["India","Military industry","Soviet diaspora","Technology transfer"]
});

Object.assign(window.deepArticles,{
  "soviet-military-industrial-diaspora":indianIndustryArticle({
    title:"Soviet military-industrial diaspora",eyebrow:"Technical migration · 1946 onward",infoboxKicker:"Dispersal of Soviet design institutions",flag:diasporaDiagram,
    lead:"<!-- altwwii-writer-block:start id=wb-g-20260816-s0a1a writer=g kind=revision created=2026-08-16T02:21:00-06:00 -->Engineers and designers from former Soviet firms and arms plants retreat into small Russian successor states, then many move into different Indian successor states when those governments invite them as industrial claimants.<sup class='canon-note' data-provenance='a'>[a]</sup> The migration transfers technical lineages and helps turn historically Soviet postwar designs into competing Indian systems.<sup class='canon-note' data-provenance='a'>[a]</sup> A complete two-stage institutional diaspora is compatible reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260816-s0a1b writer=g kind=revision created=2026-08-16T02:21:00-06:00 -->Retreat of Soviet engineers into Russian successors, subsequent recruitment by multiple Indian states, division rather than concentration of teams, transfer of tank, jet, rifle, and other design traditions, emergence of Indian versions of Soviet-derived systems, and service use of otherwise experimental designs are established.<sup class='canon-note' data-provenance='a'>[a]</sup> A formal two-stage migration, full destination list, team-and-archive packages, exact distribution among Indian states, paired bureaus, long-term community structure, dates, totals, contracts, rosters, and archive movements are incorporated extrapolation or open.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"what-moved",title:"Working contents of the migration",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-s0a1c writer=g kind=revision created=2026-08-16T02:21:00-06:00 --><p>The author establishes movement by firms, projects, individuals, researchers, designers, and engineers.<sup class='canon-note' data-provenance='a'>[a]</sup> Senior teams, metallurgists, toolmakers, draftsmen, test and production personnel, archives, gauges, tools, and prototype components are compatible detail.<sup class='canon-note' data-provenance='e'>[e]</sup> Whole firms need not remain legally intact.</p><!-- altwwii-writer-block:end -->"},
      {id:"first-retreat",title:"Retreat into Russian successor states",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-s0a1d writer=g kind=revision created=2026-08-16T02:21:00-06:00 --><p>Former Soviet industrial personnel first retreat into Russian successor states, including the limited but relatively industrial Omsk–Novosibirsk system; Novosibirsk and Magnitogorsk are examples of later cooperating locations.<sup class='canon-note' data-provenance='a'>[a]</sup> A 1945–46 chronology and full list including Nizhny Tagil, Sverdlovsk, Chelyabinsk, Ural towns, and Central Asian plants are incorporated reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"surplus",title:"Limited Russian industrial capacity",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-s0a1e writer=g kind=revision created=2026-08-16T02:21:00-06:00 --><p>Russian successor states are small and industrially constrained relative to the populations and demand available in India.<sup class='canon-note' data-provenance='a'>[a]</sup> Their inability to sustain every inherited aircraft, gun, engine, vehicle, and prototype program is compatible institutional explanation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"second-migration",title:"Migration to India",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-s0a1f writer=g kind=revision created=2026-08-16T02:21:00-06:00 --><p>As the first phase of Indian wars draws toward a close, multiple <a href='india-successors.html'>Indian successor states</a> invite Russian researchers and designers as industrial claimants; they do not all go to Congress India or Hindustan.<sup class='canon-note' data-provenance='a'>[a]</sup> A formal <a href='industrial-asylum.html'>industrial-asylum</a> system, recipient list, and national arsenal package are incorporated extrapolation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"distribution",title:"Working divided inheritance",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-s0a1g writer=g kind=revision created=2026-08-16T02:21:00-06:00 --><p>Technical personnel divide among Indian national states and princely states, some of which profit from arms and armor exports.<sup class='canon-note' data-provenance='a'>[a]</sup> Assigning medium armor and mass ordnance to Congress, ambitious armor and aviation to Hindustan, heavy prototypes to Hyderabad, dispersed weapons to TPS, and wheeled systems to western states is incorporated allocation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"not-copying",title:"Indian design development",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-s0a1h writer=g kind=revision created=2026-08-16T02:21:00-06:00 --><p>Historically Soviet postwar tank, jet, rifle, and experimental design traditions become competing Indian designs after their developers migrate.<sup class='canon-note' data-provenance='a'>[a]</sup> Specific redesign for heat, dust, monsoon, railways, bridges, steel, tooling, ammunition, and doctrine is compatible technical extrapolation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"diaspora-society",title:"Working technical communities",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-s0a1i writer=g kind=revision created=2026-08-16T02:21:00-06:00 --><p>Russian engineers and their expertise settle in Indian states.<sup class='canon-note' data-provenance='a'>[a]</sup> Stable <a href='russian-technical-communities-india.html'>industrial communities</a>, translators, bilingual manuals, local citizenship, language change, family formation, and declining expectation of return are incorporated social extrapolation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"legacy",title:"Working long-term relationship",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-s0a1j writer=g kind=revision created=2026-08-16T02:21:00-06:00 --><p>The author proposes that related teams may work in both Russian and Indian successor states and exchange designs in either direction, while larger Indian populations support Indianized systems.<sup class='canon-note' data-provenance='a'>[a]</sup> Paired bureaus, thousands of trainees, long production series, Indian seniority by the 1970s, and international classification practices remain compatible extrapolation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"}
    ],
    related:[{href:"industrial-asylum.html",kicker:"Migration institution",label:"Industrial Asylum in India"},{href:"paired-design-bureau-system.html",kicker:"Organizational form",label:"Paired Design-Bureau System"},{href:"indian-armored-design-genealogies.html",kicker:"Technical distribution",label:"Indian Armored Design Genealogies"},{href:"siberia.html",kicker:"First refuge",label:"Russia Beyond the Urals"}],
    facts:[["Established first movement","Soviet personnel into Russian successor states"],["Established second movement","Researchers and designers into multiple Indian successor states"],["Established Russian constraint","Small population and limited industrial capacity"],["Established Indian result","Competing Indian systems derived from Soviet design traditions"],["Established example","Vijaya and broad AK-47 adoption"],["Paired bureaus and detailed institutional structure","Working reconstruction"],["Dates, totals, contracts, rosters, and archive movements","Open"]]
  }),

  "industrial-asylum":indianIndustryArticle({
    title:"Industrial asylum in India",eyebrow:"Technical migration policy · late 1940s onward",infoboxKicker:"Protected residence for industrial teams",flag:diasporaDiagram,
    lead:"<!-- altwwii-writer-block:start id=wb-g-20260816-i1b2a writer=g kind=revision created=2026-08-16T02:22:15-06:00 -->Indian successor states invite displaced Russian researchers and designers as industrial claimants, competing for expertise that can create local arms industries.<sup class='canon-note' data-provenance='a'>[a]</sup> A defined practice of <strong>industrial asylum</strong> involving protected workshops, residence, contracts, and institutional status is compatible reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260816-i1b2b writer=g kind=revision created=2026-08-16T02:22:15-06:00 -->Invitations from multiple Indian successor states, division of Russian personnel among different hosts, princely-state participation in profitable arms manufacture, and competitive demand for industrial expertise are established.<sup class='canon-note' data-provenance='a'>[a]</sup> The industrial-asylum label, protected-residence system, standard inducements, recognized lineage claims, contract market, brokers, coercion, legal categories, late-1940s start, treaties, and archives are incorporated extrapolation or open.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"demand",title:"Demand from permanent war",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-i1b2c writer=g kind=revision created=2026-08-16T02:22:15-06:00 --><p>Indian states have larger populations and wartime demand than the small Russian successors, and they invite Russian designers to establish Indian production.<sup class='canon-note' data-provenance='a'>[a]</sup> Their precise manpower, tax, workshop, and railway advantages and preference for technical capacity over ideology are compatible institutional explanation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"offer",title:"Working asylum package",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-i1b2d writer=g kind=revision created=2026-08-16T02:22:15-06:00 --><p>Government housing, guarded workshops, commodity salaries, multi-year contracts, apprenticeship authority, bonuses, royalties, and residence for families are compatible inducements.<sup class='canon-note' data-provenance='e'>[e]</sup> The author establishes invitations but not their legal or material terms.</p><!-- altwwii-writer-block:end -->"},
      {id:"claimants",title:"Working industrial lineage claims",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-i1b2e writer=g kind=revision created=2026-08-16T02:22:15-06:00 --><p>The author describes migrants as industrial claimants and identifies firms, projects, developers, researchers, and designers.<sup class='canon-note' data-provenance='a'>[a]</sup> Archives, test records, tooling knowledge, senior-personnel recognition, and government production tests are compatible elaboration.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"competition",title:"Competition among successor states",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-i1b2f writer=g kind=revision created=2026-08-16T02:22:15-06:00 --><p>Personnel divide among Congress India, Hindustan, and various other national and princely states rather than concentrating in one host.<sup class='canon-note' data-provenance='a'>[a]</sup> Specific offers of Congress scale, Hindustani prestige, Hyderabadi privilege, TPS ideology, and western commercial freedom are incorporated allocation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"brokers",title:"Working talent brokers",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-i1b2g writer=g kind=revision created=2026-08-16T02:22:15-06:00 --><p>Private arms dealers are established as wealthy intermediaries in northern India.<sup class='canon-note' data-provenance='a'>[a]</sup> Their arranging travel, housing, family movement, introductions, tools, commodity payment, drawings, and recruitment of specialist teams is compatible extrapolation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"coercion",title:"Working coercive competition",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-i1b2h writer=g kind=revision created=2026-08-16T02:22:15-06:00 --><p>Defection campaigns, archive theft, intimidation, kidnapping, and targeted recruitment of engineers with production knowledge are plausible consequences of technical competition.<sup class='canon-note' data-provenance='e'>[e]</sup> No such operation is directly established.</p><!-- altwwii-writer-block:end -->"},
      {id:"law",title:"Working legal settlements",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-i1b2i writer=g kind=revision created=2026-08-16T02:22:15-06:00 --><p>Engineers serving as civil servants, arsenal employees, contractors, royal retainers, officers, or protected residents, with host-specific family citizenship, is compatible legal extrapolation.<sup class='canon-note' data-provenance='e'>[e]</sup> No common refugee law or national category is established.</p><!-- altwwii-writer-block:end -->"},
      {id:"legacy",title:"Working institutional development",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-i1b2j writer=g kind=revision created=2026-08-16T02:22:15-06:00 --><p>Russian-derived designs become Indian systems and some otherwise experimental designs enter service because particular designers are available to particular states.<sup class='canon-note' data-provenance='a'>[a]</sup> Asylum groups training local engineers, translating manuals, setting tests, becoming named bureaus, and retaining Russian shop vocabulary are compatible extrapolation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"}
    ],
    related:[{href:"soviet-military-industrial-diaspora.html",kicker:"Wider movement",label:"Soviet Military-Industrial Diaspora"},{href:"paired-design-bureau-system.html",kicker:"Institutional consequence",label:"Paired Design-Bureau System"},{href:"russian-technical-communities-india.html",kicker:"Human consequence",label:"Russian Technical Communities"},{href:"indian-bullion-economy.html",kicker:"Hard payment system",label:"Indian Bullion Economy"}],
    facts:[["Established practice","Indian states invite Russian industrial claimants"],["Established recipients","Researchers, designers, firms, and projects"],["Established market","Multiple national and princely hosts"],["Established result","Competing Indian design systems"],["Industrial-asylum label, package, law, and brokerage","Working reconstruction"],["Start date, contracts, residence, payments, and coercive incidents","Open"]]
  }),

  "paired-design-bureau-system":indianIndustryArticle({
    title:"Paired design-bureau system",eyebrow:"Transnational engineering system · 1950s onward",infoboxKicker:"Northern and southern branch bureaus",flag:diasporaDiagram,
    lead:"<!-- altwwii-writer-block:start id=wb-g-20260816-q7c3a writer=g kind=revision created=2026-08-16T02:23:45-06:00 -->A <strong>paired design-bureau system</strong>, with related teams operating in Russian and Indian successor states and exchanging designs, is a working development suggested by the movement of Soviet technical personnel.<sup class='canon-note' data-provenance='e'>[e]</sup> The underlying migration and Indianization of Soviet-derived designs are established; a formal paired-bureau arrangement is not.<sup class='canon-note' data-provenance='a'>[a]</sup><!-- altwwii-writer-block:end -->",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260816-q7c3b writer=g kind=revision created=2026-08-16T02:23:45-06:00 -->Russian personnel settling in both Russian and Indian successor states, Indian states developing Soviet-derived systems, and the possibility of cooperation and design exchange in either direction are established context.<sup class='canon-note' data-provenance='a'>[a]</sup> Northern and southern branch offices, shared archives, continuing exchanges, environmental divergence, authenticity disputes, later Indian seniority, dates, bureau counts, contracts, patents, and corporate names are incorporated extrapolation or open.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"split",title:"Working division of a bureau",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-q7c3c writer=g kind=revision created=2026-08-16T02:23:45-06:00 --><p>The author suggests that related teams might work from places such as Novosibirsk or Magnitogorsk and India, with designs moving south or north.<sup class='canon-note' data-provenance='a'>[a]</sup> Offices at Omsk or Nizhny Tagil, a Congress production branch, and independent Hyderabadi or Hindustani groups with shared papers are incorporated examples.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"north",title:"Working northern branch",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-q7c3d writer=g kind=revision created=2026-08-16T02:23:45-06:00 --><p>Russian offices optimizing for cold starting, winter roads, short production, Siberian maintenance, and limited scale while claiming institutional authenticity are compatible technical and legal extrapolation.<sup class='canon-note' data-provenance='e'>[e]</sup> No northern-branch organization is fixed.</p><!-- altwwii-writer-block:end -->"},
      {id:"south",title:"Working southern branch",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-q7c3e writer=g kind=revision created=2026-08-16T02:23:45-06:00 --><p>Indian offices redesigning for heat, dust, monsoon campaigning, conscript armies, rail loading, local steel and ammunition, and larger production is compatible with Indianized Soviet-derived design.<sup class='canon-note' data-provenance='e'>[e]</sup> The exact requirements and scale are open.</p><!-- altwwii-writer-block:end -->"},
      {id:"exchange",title:"Working two-way exchange",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-q7c3f writer=g kind=revision created=2026-08-16T02:23:45-06:00 --><p>Two-way design cooperation is an explicit possibility in the source.<sup class='canon-note' data-provenance='a'>[a]</sup> Continuing movement of archives, tests, specialists, components, funding, and field modifications through Central Asia and Afghanistan is incorporated logistical extrapolation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"identity",title:"Working authenticity disputes",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-q7c3g writer=g kind=revision created=2026-08-16T02:23:45-06:00 --><p>Russian claims based on origin and continuity and Indian claims based on financing, factories, trials, redesign, and combat use are compatible institutional disputes.<sup class='canon-note' data-provenance='e'>[e]</sup> No recorded dispute or governing doctrine is directly established.</p><!-- altwwii-writer-block:end -->"},
      {id:"generation",title:"Working second generation",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-q7c3h writer=g kind=revision created=2026-08-16T02:23:45-06:00 --><p>Indian apprentices eventually staffing the southern offices, with Russian retained in archives and shop terms while local languages govern production, is compatible social extrapolation.<sup class='canon-note' data-provenance='e'>[e]</sup> Training and language patterns remain open.</p><!-- altwwii-writer-block:end -->"},
      {id:"competition",title:"Competing design paths",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-q7c3i writer=g kind=revision created=2026-08-16T02:23:45-06:00 --><p>Competing designers migrate to different Indian states, allowing historically experimental designs to enter service when a state has no alternative designer.<sup class='canon-note' data-provenance='a'>[a]</sup> Assigning a mass tank to Congress, ambitious armor to Hindustan, a heavy vehicle to Hyderabad, and a cold-weather cousin to Siberia is incorporated allocation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"legacy",title:"Working transnational families",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-q7c3j writer=g kind=revision created=2026-08-16T02:23:45-06:00 --><p>Sibling systems retaining design resemblance while diverging in climate adaptation, metallurgy, radios, ammunition, tolerances, and doctrine by the mid-1960s is compatible technical extrapolation.<sup class='canon-note' data-provenance='e'>[e]</sup> Interchangeability and dates remain open.</p><!-- altwwii-writer-block:end -->"}
    ],
    related:[{href:"soviet-military-industrial-diaspora.html",kicker:"Origin",label:"Soviet Military-Industrial Diaspora"},{href:"vijaya-tank.html",kicker:"Best-known southern branch",label:"Vijaya"},{href:"indian-armored-design-genealogies.html",kicker:"Competing branches",label:"Indian Armored Design Genealogies"},{href:"industrial-asylum.html",kicker:"Recruitment system",label:"Industrial Asylum"}],
    facts:[["Established context","Russian expertise migrates into Russian and Indian successor states"],["Established possibility","Related teams and designs cooperate north–south"],["Formal paired-bureau system","Working reconstruction"],["Branches, archives, adaptations, and disputes","Working reconstruction"],["Dates, bureau counts, contracts, patents, and corporate identities","Open"]]
  }),

  "indian-armored-design-genealogies":indianIndustryArticle({
    title:"Indian armored design genealogies",eyebrow:"Armored-vehicle industry · 1950s–1980s",infoboxKicker:"Fragmented Soviet technical inheritance",flag:genealogyDiagram,
    lead:"<!-- altwwii-writer-block:start id=wb-g-20260816-g8d4a writer=g kind=revision created=2026-08-16T02:26:40-06:00 -->Russian armored-vehicle researchers and designers split among different Indian successor states, allowing competing Soviet-derived and historically experimental design paths to become Indian service systems.<sup class='canon-note' data-provenance='a'>[a]</sup> Allocation of particular Soviet bureaus and vehicle families to Congress India, Hindustan, Hyderabad, Rajputana, Kashmir, Khalistan, and Pakistani successors is incorporated reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260816-g8d4b writer=g kind=revision created=2026-08-16T02:26:40-06:00 -->Division of Russian developers among multiple Indian states, development of Indian versions of Soviet-derived tanks and other systems, service use of some historically experimental designs, Congress India's Vijaya, princely arms manufacture, and chemical warfare as a regional armored-design pressure are established.<sup class='canon-note' data-provenance='a'>[a]</sup> Exact Kartsev, Nizhny Tagil, Kurgan, Morozov, Kharkiv, Mytishchi, Kotin, Kirov, Uralmash, Astrov, and GAZ–Arzamas allocations, state-specific heavy and light branches, aviation division, names, specifications, totals, and dates are extrapolated or open.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"fragmentation",title:"Fragmented procurement",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-g8d4c writer=g kind=revision created=2026-08-16T02:26:40-06:00 --><p>Designers split among different Indian states, so competing and otherwise experimental designs can enter service when a particular state has access to a particular developer.<sup class='canon-note' data-provenance='a'>[a]</sup> Absence of a central procurement ministry and team availability outweighing an ideal design are compatible institutional explanation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"congress",title:"Working Congress lineage",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-g8d4d writer=g kind=revision created=2026-08-16T02:26:40-06:00 --><p>Congress India develops the T-55-like National Tank Model 62 or <a href='vijaya-tank.html'>Vijaya</a> through Russian tank-developer migration.<sup class='canon-note' data-provenance='a'>[a]</sup> Kartsev–Nizhny Tagil and Chelyabinsk–Kurgan assignments, carriers, recovery and engineer chassis, artillery, and standardized mass-army doctrine are incorporated extrapolation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"hindustan",title:"Working Hindustan lineage",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-g8d4e writer=g kind=revision created=2026-08-16T02:26:40-06:00 --><p>Russian developers migrate to Hindustan as well as other Indian states.<sup class='canon-note' data-provenance='a'>[a]</sup> Morozov–Kharkiv Object 430–435–432 armor, Mytishchi air defense, aviation expertise, and a sophisticated but maintenance-intensive industrial character are incorporated allocation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"heavy",title:"Working princely heavy branches",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-g8d4f writer=g kind=revision created=2026-08-16T02:26:40-06:00 --><p>Some princely states attract Russian industrial personnel and profit by building and exporting arms and armor.<sup class='canon-note' data-provenance='a'>[a]</sup> Assigning Kotin–Kirov and Uralmash heavy systems to <a href='hyderabadi-arms-industry.html'>Hyderabad</a> and a rival Chelyabinsk school to Rajputana is incorporated extrapolation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"light",title:"Working frontier vehicle branches",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-g8d4g writer=g kind=revision created=2026-08-16T02:26:40-06:00 --><p>Astrov-derived light vehicles in Khalistan and Kashmir and GAZ–Arzamas wheeled armor in Pakistani and Indus states are compatible responses to mountain, desert, river, road, and patrol requirements.<sup class='canon-note' data-provenance='e'>[e]</sup> No such bureau allocation or vehicle family is directly established.</p><!-- altwwii-writer-block:end -->"},
      {id:"prototypes",title:"Experimental designs in service",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-g8d4h writer=g kind=revision created=2026-08-16T02:26:40-06:00 --><p>Designs that remained experimental in real history can enter Indian service because a state may possess only the relevant designer.<sup class='canon-note' data-provenance='a'>[a]</sup> Short-run Object-derived tanks, assault guns, carriers, and air-defense machines purchased by specific courts or ministries are compatible examples.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"chemical",title:"Chemical-protection pressure",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-g8d4i writer=g kind=revision created=2026-08-16T02:26:40-06:00 --><p>Chemical weapons are used in an Indian war and influence regional armored development.<sup class='canon-note' data-provenance='a'>[a]</sup> Filtered overpressure, sealing, cooling, detection, decontamination, and enclosed infantry transport becoming standard across every branch are incorporated technical extrapolation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"judgment",title:"Working quality and quantity debate",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-g8d4j writer=g kind=revision created=2026-08-16T02:26:40-06:00 --><p>A Hindustani quality claim answered by Congress arguments for availability, support, and standardized scale is compatible doctrinal interpretation.<sup class='canon-note' data-provenance='e'>[e]</sup> No such debate or fixed Congress–Hindustan industrial contrast is directly established.</p><!-- altwwii-writer-block:end -->"}
    ],
    related:[{href:"vijaya-tank.html",kicker:"Congress family",label:"Vijaya"},{href:"congress-indian-ordnance-system.html",kicker:"Mass-production system",label:"Congress Indian Ordnance System"},{href:"hindustani-military-industry.html",kicker:"Advanced rival",label:"Hindustani Military Industry"},{href:"hyderabadi-arms-industry.html",kicker:"Heavy and commercial branch",label:"Hyderabadi Arms Industry"}],
    facts:[["Established origin","Russian developers divide among Indian successor states"],["Established result","Competing Indian systems, including former experimental paths"],["Established Congress vehicle","National Tank Model 62 / Vijaya"],["Established princely role","Some states manufacture and export arms and armor"],["Established later pressure","Chemical warfare influences armored design"],["Exact bureau and vehicle-family allocations","Working reconstruction"],["Names, specifications, totals, and adoption dates","Open"]]
  }),

  "vijaya-tank":indianIndustryArticle({
    title:"Vijaya",eyebrow:"Congress Indian tank · first wartime showing about 1963",infoboxKicker:"National Tank Model 62",flag:vijayaDiagram,
    lead:"<!-- altwwii-writer-block:start id=wb-g-20260816-v8r9a writer=g kind=revision created=2026-08-16T01:22:37-06:00 --><strong>Vijaya</strong>, also described as Congress India's <strong>National Tank Model 62</strong>, first appears in the northern war beginning about 1963 and is sufficiently comparable to advanced Japanese tanks to concern Azad Hind.<sup class='canon-note' data-provenance='a'>[a]</sup> Its T-54 and T-55 ancestry through displaced Nizhny Tagil personnel, tropical redesign, domestic production system, later variants, and precise service history are incorporated technical development.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260816-v8r9b writer=g kind=revision created=2026-08-16T01:22:37-06:00 -->The National Tank Model 62 and Vijaya names, Congress Indian ownership, first showing in the northern war beginning about 1963, and rough comparability with technically superior Japanese tanks are established.<sup class='canon-note' data-provenance='a'>[a]</sup> Whether Model 62 and Vijaya are formal and popular names for one design remains slightly open in the author's phrasing.<sup class='canon-note' data-provenance='a'>[a]</sup> The Kartsev–Nizhny Tagil and T-54/T-55 lineage, service by 1962, tropical and production redesign, detailed war performance, Vijaya A protection package, and later family are incorporated extrapolation.<sup class='canon-note' data-provenance='e'>[e]</sup> Formal designation, ancestry, dimensions, gun, factories, production totals, variants, and dates remain open.<!-- altwwii-writer-block:end -->",
    primarySources:[{href:"https://en.wikipedia.org/wiki/T-54/T-55",label:"T-54/T-55 — historical technical ancestry"}],
    sections:[
      {id:"origin",title:"Working Nizhny Tagil ancestry",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-v8r9c writer=g kind=revision created=2026-08-16T01:22:37-06:00 --><p>The proposed genealogy places displaced Nizhny Tagil and Kartsev personnel in Congress India with T-54, T-55, diesel, transmission, turret, suspension, manufacturing, and partial Object 140 knowledge.<sup class='canon-note' data-provenance='e'>[e]</sup> The author establishes a wider migration of Russian military-industrial expertise into Indian successor states but does not directly assign this bureau or lineage to Congress India.<sup class='canon-note' data-provenance='a'>[a]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"indianization",title:"Working Indianization of the design",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-v8r9d writer=g kind=revision created=2026-08-16T01:22:37-06:00 --><p>Redesign of cooling, dust filtration, electrical sealing, stowage, radios, ammunition, armor grades, railway loading, bridge weight, and production methods is a compatible account of adapting a Russian-derived tank to Indian manufacture and service.<sup class='canon-note' data-provenance='e'>[e]</sup> The exact requirements and solutions remain open.</p><!-- altwwii-writer-block:end -->"},
      {id:"model62",title:"National Tank Model 62 or Vijaya",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-v8r9e writer=g kind=revision created=2026-08-16T01:22:37-06:00 --><p>The author names the vehicle both <strong>National Tank Model 62</strong> and <strong>Vijaya</strong> and places its first showing in the war beginning about 1963.<sup class='canon-note' data-provenance='a'>[a]</sup> Entry into service around 1962, a mature production standard, Russian layout and diesel practice, and useful-scale production across the Ganges system are plausible reconstructions.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"war",title:"Northern Indian War",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-v8r9f writer=g kind=revision created=2026-08-16T01:22:37-06:00 --><p>Vijaya appears in the northern war beginning about 1963 and provides Azad Hind with a credible local opponent to its more advanced Japanese tanks.<sup class='canon-note' data-provenance='a'>[a]</sup> Identifying those Japanese vehicles as Type 16 Shu-Ha and specifying rail, bridge, monsoon, infantry, recovery, filtration, and ammunition constraints as the decisive comparison are compatible operational synthesis.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"vijaya-a",title:"Working Vijaya A",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-v8r9g writer=g kind=revision created=2026-08-16T01:22:37-06:00 --><p>Chemical-weapon use in an Indian war is established as an influence on regional armored design.<sup class='canon-note' data-provenance='a'>[a]</sup> A <strong>Vijaya A</strong> with tighter seals, filtered positive pressure, protected crew air, automatic intake closure, better cooling, revised ammunition stowage, and chemical-warning interfaces is incorporated technical extrapolation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"family",title:"Working wider family",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-v8r9h writer=g kind=revision created=2026-08-16T01:22:37-06:00 --><p>Object 140-derived gun experiments, a longer-gunned successor in the broad role of the historical T-62, and common recovery, engineer, command, reconnaissance, and decontamination chassis form a compatible proposed family.<sup class='canon-note' data-provenance='e'>[e]</sup> None is yet directly established.</p><!-- altwwii-writer-block:end -->"},
      {id:"production",title:"Quantity as a working doctrine",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-v8r9i writer=g kind=revision created=2026-08-16T01:22:37-06:00 --><p>A Congress preference for standardized quantity, domestic spares, trained crews, reserve formations, and availability across several fronts is compatible with the state's defensive survival and large mobilized population.<sup class='canon-note' data-provenance='e'>[e]</sup> Its exact production doctrine and debate with Hindustan remain open.</p><!-- altwwii-writer-block:end -->"},
      {id:"identity",title:"An Indian tank",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-v8r9j writer=g kind=revision created=2026-08-16T01:22:37-06:00 --><p>Congress India's ownership of Vijaya is established.<sup class='canon-note' data-provenance='a'>[a]</sup> Congress control of the program, factory, trials, doctrine, and continuing development, together with central Russian émigré participation, is a compatible institutional explanation for treating it as an Indian rather than imported tank.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"}
    ],
    related:[{href:"congress-india.html",kicker:"Operator",label:"Congress India"},{href:"congress-indian-ordnance-system.html",kicker:"Industrial base",label:"Congress Indian Ordnance System"},{href:"indian-armored-design-genealogies.html",kicker:"Competing families",label:"Indian Armored Design Genealogies"},{href:"northern-indian-war.html",kicker:"Combat history",label:"Northern Indian War"}],
    facts:[["Established names","National Tank Model 62; Vijaya"],["State","Congress India"],["First established appearance","Northern war beginning about 1963"],["Established comparison","Comparable local opponent to technically superior Japanese tanks"],["Formal relationship of the two names","Open"],["Technical ancestry","Working Kartsev–Nizhny Tagil / T-54 and T-55 genealogy"],["Variants and specifications","Open; Vijaya A is working extrapolation"]]
  }),

  "congress-indian-ordnance-system":indianIndustryArticle({
    title:"Congress Indian ordnance system",eyebrow:"National military industry · 1950s onward",infoboxKicker:"Mass-production arsenal system",flag:genealogyDiagram,
    lead:"<!-- altwwii-writer-block:start id=wb-g-20260816-c1o5a writer=g kind=revision created=2026-08-16T02:31:00-06:00 -->Congress India develops domestic weapons and supplies as the first Indian wars continue, later fields the Russian-migration-enabled <a href='vijaya-tank.html'>Vijaya</a>, and maintains forces across several fortified frontiers.<sup class='canon-note' data-provenance='a'>[a]</sup> A unified mass-production arsenal made from specified state arsenals, British workshops, railway institutions, schools, and émigré bureaus is incorporated institutional reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260816-c1o5b writer=g kind=revision created=2026-08-16T02:31:00-06:00 -->Congress India's growing domestic military supply, Russian technical migration, Vijaya development, large conscripted force, defensive orientation, and multiple hostile frontiers are established.<sup class='canon-note' data-provenance='a'>[a]</sup> Its claimed primacy in northern production, formal arsenal network, absorption rules, Nizhny Tagil and Omsk assignments, specialization, standardization doctrine, factory geography, budgets, products, and production totals remain extrapolated or open.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"inheritance",title:"Inherited Indian foundations",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-c1o5c writer=g kind=revision created=2026-08-16T02:31:00-06:00 --><p>Congress India initially fields mixed older British equipment and Russian matériel obtained through private dealers, then develops its own supplies and weapons as the 1950s continue.<sup class='canon-note' data-provenance='a'>[a]</sup> A middle-Ganges base of civil-service cadres, railway workshops, arsenals, and schools able to sustain long production runs is compatible but not directly specified.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"absorption",title:"Working national-arsenal model",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-c1o5d writer=g kind=revision created=2026-08-16T02:31:00-06:00 --><p>Russian researchers and designers migrate into Congress India as well as other Indian states.<sup class='canon-note' data-provenance='a'>[a]</sup> Their placement inside public ordnance, apprentice requirements, translated documentation, domestic tooling, and eventual Indian management are incorporated institutional extrapolation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"armor",title:"Armored development",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-c1o5e writer=g kind=revision created=2026-08-16T02:31:00-06:00 --><p>The <a href='vijaya-tank.html'>Vijaya</a>, or National Tank Model 62, is a Congress Indian design enabled by Russian tank-developer migration.<sup class='canon-note' data-provenance='a'>[a]</sup> Nizhny Tagil, Omsk, and Chelyabinsk–Kurgan assignments and a standardized family of carriers and specialist chassis are incorporated genealogy.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"artillery",title:"Domestic supply",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-c1o5f writer=g kind=revision created=2026-08-16T02:31:00-06:00 --><p>Congress India develops domestic supplies and weapons until its capacity becomes comparable to Azad Hind's resuming foreign supply.<sup class='canon-note' data-provenance='a'>[a]</sup> Particular strength in field artillery, guns, ammunition, propellant, and railway military transport is compatible specialization rather than a settled product list.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"doctrine",title:"Production and defensive war",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-c1o5g writer=g kind=revision created=2026-08-16T02:31:00-06:00 --><p>Congress India uses its large population, conscription, entrenchment, and defensive orientation to hold several frontiers during the northern wars.<sup class='canon-note' data-provenance='a'>[a]</sup> A formal doctrine preferring standardized, easily manufactured and repaired equipment in useful numbers is compatible interpretation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"chemical",title:"Chemical-protection pressure",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-c1o5h writer=g kind=revision created=2026-08-16T02:31:00-06:00 --><p>Chemical warfare influences regional armored design.<sup class='canon-note' data-provenance='a'>[a]</sup> Treating sealed vehicles, collective filtration, decontamination equipment, protected command posts, and enclosed infantry transport as one standardized Congress system is incorporated technical extrapolation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"limits",title:"Working limits of the system",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-c1o5i writer=g kind=revision created=2026-08-16T02:31:00-06:00 --><p>Variable factory quality, lagging electronics, strain in supplying a large army, and an advantage in continuity and numbers over technical elegance are compatible assessments.<sup class='canon-note' data-provenance='e'>[e]</sup> The transcript establishes no settled comparative industrial ranking between Congress India and Hindustan.</p><!-- altwwii-writer-block:end -->"},
      {id:"legacy",title:"An Indian design tradition",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-c1o5j writer=g kind=revision created=2026-08-16T02:31:00-06:00 --><p>Formerly Soviet postwar designs become Indian systems as Russian personnel divide among Indian hosts, and Congress India's Vijaya is the clearest established result.<sup class='canon-note' data-provenance='a'>[a]</sup> Generations of Indian engineers, continuing finance independent of Siberian partners, and a formally unified national ordnance tradition are compatible later development.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"}
    ],
    related:[{href:"congress-india.html",kicker:"National state",label:"Congress India"},{href:"vijaya-tank.html",kicker:"Principal product",label:"Vijaya"},{href:"soviet-military-industrial-diaspora.html",kicker:"Technical origin",label:"Soviet Military-Industrial Diaspora"},{href:"northern-indian-war.html",kicker:"Operational test",label:"Northern Indian War"}],
    facts:[["Established development","Domestic supplies, weapons, and armored research"],["State","Congress India"],["Established technical source","Russian personnel divided among Indian states"],["Established vehicle","National Tank Model 62 / Vijaya"],["Established strategic condition","Large conscript force on fortified multiple frontiers"],["Exact bureaus and arsenal structure","Working reconstruction"],["Specializations and standardization doctrine","Working interpretation"],["Names, factories, budgets, and production totals","Open"]]
  }),

  "hindustani-military-industry":indianIndustryArticle({
    title:"Military industry of Hindustan",eyebrow:"Aviation, air defense, and advanced armor · 1950s onward",infoboxKicker:"Hindustani defense industry",flag:genealogyDiagram,
    lead:"<!-- altwwii-writer-block:start id=wb-g-20260816-h3m6a writer=g kind=revision created=2026-08-16T02:32:00-06:00 -->Hindustan obtains mixed older British and Russian equipment, receives part of the Russian military-industrial migration into India, and is expected to develop indigenous aircraft as northern India's long arms buildup continues.<sup class='canon-note' data-provenance='a'>[a]</sup> Specialization in MiG-oriented aviation, radar, mobile air defense, communications, and Morozov-derived armor is incorporated design-lineage reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260816-h3m6b writer=g kind=revision created=2026-08-16T02:32:00-06:00 -->Hindustan's mixed imported arsenal, share of Russian technical migration, eventual indigenous aircraft development, permanent war footing, and concern with Congress India and the Pakistani successor states are established.<sup class='canon-note' data-provenance='a'>[a]</sup> MiG, Novosibirsk, Morozov–Kharkiv, Mytishchi, radar, and air-defense allocations, a fixed sophistication-versus-maintenance contrast with Congress India, bureau names, designs, factories, and production totals remain extrapolated or open.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"strategy",title:"A state facing several directions",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-h3m6c writer=g kind=revision created=2026-08-16T02:32:00-06:00 --><p>Hindustan wants to contest Congress India, but Pakistani successor states are its principal immediate concern and prevent expansion toward Kashmir; like the other northern states, it has more than one enemy.<sup class='canon-note' data-provenance='a'>[a]</sup> The exact frontier list and its effects on industrial planning remain interpretive.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"aviation",title:"Working aviation lineage",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-h3m6d writer=g kind=revision created=2026-08-16T02:32:00-06:00 --><p>The author expects Hindustan, like Congress India, to begin developing its own fighter aircraft around the 1970s or 1980s after years of examining imported equipment.<sup class='canon-note' data-provenance='a'>[a]</sup> Novosibirsk personnel, displaced Soviet offices, MiG primacy, engines, overhaul, and airfield systems are compatible but unconfirmed allocations.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"radar",title:"Working radar and mobile air defense",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-h3m6e writer=g kind=revision created=2026-08-16T02:32:00-06:00 --><p>Foreign anti-aircraft guns and missiles enter northern India through arms dealers while the states build domestic capacity.<sup class='canon-note' data-provenance='a'>[a]</sup> A Mytishchi-derived Hindustani branch of tracked air defense, radar integration, and mobile command is incorporated extrapolation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"armor",title:"Working Morozov–Kharkiv family",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-h3m6f writer=g kind=revision created=2026-08-16T02:32:00-06:00 --><p>Russian designers split among Indian states, allowing particular historical and experimental paths to become Indian service systems.<sup class='canon-note' data-provenance='a'>[a]</sup> Hindustani possession of the Morozov–Kharkiv Object 430–435–432 tradition and T-64-like vehicles is incorporated genealogy.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"comparison",title:"Working rivalry with Vijaya",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-h3m6g writer=g kind=revision created=2026-08-16T02:32:00-06:00 --><p>Hindustan and Congress India are rivals, and Congress India's <a href='vijaya-tank.html'>Vijaya</a> is established.<sup class='canon-note' data-provenance='a'>[a]</sup> A debate between fewer superior Hindustani tanks and more maintainable Vijayas, including any settled battlefield verdict, is compatible interpretation rather than direct canon.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"chemical",title:"Chemical-protection pressure",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-h3m6h writer=g kind=revision created=2026-08-16T02:32:00-06:00 --><p>Chemical war influences regional armored design.<sup class='canon-note' data-provenance='a'>[a]</sup> More sophisticated Hindustani sealing, filtration, cooling, sensors, and protected air-defense vehicles, offset by difficult upkeep, are incorporated technical extrapolation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"constraints",title:"Working industrial constraints",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-h3m6i writer=g kind=revision created=2026-08-16T02:32:00-06:00 --><p>Permanent mobilization, several hostile frontiers, reliance on imported equipment during the earlier period, and the wider exhaustion of northern India are established pressures.<sup class='canon-note' data-provenance='a'>[a]</sup> Imported machine-tool dependence, competing programs, limited production scale, and small fleets of elegant systems remain compatible assessment.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"legacy",title:"A proposed Soviet-derived branch",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-h3m6j writer=g kind=revision created=2026-08-16T02:32:00-06:00 --><p>Formerly Soviet postwar designs become distinct Indian designs because personnel divide among different hosts.<sup class='canon-note' data-provenance='a'>[a]</sup> Hindustan's specific national identity in compact, mobile, technically ambitious systems is a coherent proposed branch, not yet settled canon.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"}
    ],
    related:[{href:"hindustan.html",kicker:"National state",label:"Hindustan"},{href:"indian-armored-design-genealogies.html",kicker:"Armored rivalry",label:"Indian Armored Design Genealogies"},{href:"soviet-military-industrial-diaspora.html",kicker:"Technical origin",label:"Soviet Military-Industrial Diaspora"},{href:"pakistan-emergency-government.html",kicker:"Western strategic pressure",label:"Pakistan Emergency Government"}],
    facts:[["Established development","Mixed imports, Russian technical migration, later indigenous aircraft"],["State","Hindustan"],["Established principal concern","Pakistani successor states"],["Established eastern rival","Congress India"],["Established strategic condition","Permanent mobilization and several enemies"],["MiG, Novosibirsk, Morozov–Kharkiv, and Mytishchi assignments","Working reconstruction"],["Sophistication and maintenance comparison","Working interpretation"],["Designations, factories, and production totals","Open"]]
  }),

  "hyderabadi-arms-industry":indianIndustryArticle({
    title:"Arms industry of Hyderabad",eyebrow:"Princely military commerce · 1950s onward",infoboxKicker:"Prototype, repair, and export center",flag:genealogyDiagram,
    lead:"<!-- altwwii-writer-block:start id=wb-g-20260816-y5a7a writer=g kind=revision created=2026-08-16T02:34:00-06:00 -->Hyderabad maintains a substantial princely guard force, imports German aircraft and other military goods, sometimes resells aircraft to neighboring powers, and shifts toward Japanese equipment and influence in the mid-1980s.<sup class='canon-note' data-provenance='a'>[a]</sup> Its identity as a domestic heavy-vehicle, artillery, overhaul, prototype, and short-run export center is incorporated industrial reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260816-y5a7b writer=g kind=revision created=2026-08-16T02:34:00-06:00 -->Hyderabad's large guard establishment, German military imports, aircraft resale, loss of special German support, and subsequent Japanese equipment and investment relationship are established.<sup class='canon-note' data-provenance='a'>[a]</sup> The wider possibility that Russian personnel settle in princely states that manufacture and export arms is also authorially proposed, but Hyderabad's Kirov, Uralmash, and Yakovlev inheritance, domestic commercial role, specializations, maritime industrial corridor, firms, products, contracts, and totals remain extrapolated or open.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"advantages",title:"A major princely military establishment",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-y5a7c writer=g kind=revision created=2026-08-16T02:34:00-06:00 --><p>Hyderabad is among the larger princely states and expressly maintains a substantial guard force during northern India's permanent war footing.<sup class='canon-note' data-provenance='a'>[a]</sup> Concentrated royal wealth, personal court contracts, a comparatively small army, and an industrial corridor through Warangal and Vijayawada to Machilipatnam are compatible reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"refuge",title:"Working market for rejected designs",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-y5a7d writer=g kind=revision created=2026-08-16T02:34:00-06:00 --><p>The author proposes that some Russian personnel may settle in princely states that profit from building and exporting weapons and armor, and establishes that otherwise experimental designs can enter Indian service when a host has the relevant designer.<sup class='canon-note' data-provenance='a'>[a]</sup> Hyderabad funding losing designs and short prototype runs is an incorporated application of that possibility.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"heavy",title:"Working Kotin–Kirov heavy tradition",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-y5a7e writer=g kind=revision created=2026-08-16T02:34:00-06:00 --><p>A Hyderabad branch formed from the Leningrad, Plant No. 100, and Chelyabinsk heavy-tank community, fielding limited descendants of late IS, T-10, and Object 277 concepts, is incorporated design genealogy.<sup class='canon-note' data-provenance='e'>[e]</sup> No Kirov allocation or resulting vehicle is directly established.</p><!-- altwwii-writer-block:end -->"},
      {id:"artillery",title:"Working Uralmash systems",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-y5a7f writer=g kind=revision created=2026-08-16T02:34:00-06:00 --><p>Uralmash-derived self-propelled artillery, assault guns, recovery machines, unusual direct-fire vehicles, and chemical-protected specialist roles are incorporated extrapolation.<sup class='canon-note' data-provenance='e'>[e]</sup> Their allocation to Hyderabad and use in short production runs remain open.</p><!-- altwwii-writer-block:end -->"},
      {id:"aviation",title:"Imported aircraft and a working Yakovlev branch",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-y5a7g writer=g kind=revision created=2026-08-16T02:34:00-06:00 --><p>Hyderabad imports German jets and other military equipment before Japanese exports increasingly replace German support in the 1980s.<sup class='canon-note' data-provenance='a'>[a]</sup> A Yakovlev-derived domestic branch for overhaul, engine rebuilding, prototypes, trainers, and military aviation is compatible but not directly established.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"export",title:"Resale and a working repair market",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-y5a7h writer=g kind=revision created=2026-08-16T02:34:00-06:00 --><p>Hyderabad sometimes resells imported German jets to neighboring powers, while arms dealers provide northern India's principal route to new foreign technology.<sup class='canon-note' data-provenance='a'>[a]</sup> Engine rebuilding, modernization, incomplete-prototype finishing, and sale of domestically produced short-run vehicles are incorporated commercial extrapolation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"japan",title:"Japanese association in the mid-1980s",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-y5a7i writer=g kind=revision created=2026-08-16T02:34:00-06:00 --><p>Germany reduces its special support for Hyderabad during the German–Japanese settlement, after which Japanese equipment, investment, and political influence expand while Hyderabad remains sovereign and distinct from Azad Hind.<sup class='canon-note' data-provenance='a'>[a]</sup> Hyderabad firms mediating among German, Japanese, and Russian-derived systems are compatible later development.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"limits",title:"Working limits of a princely arsenal",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-y5a7j writer=g kind=revision created=2026-08-16T02:34:00-06:00 --><p>Short runs, incompatible parts, personal contracts, and court politics making Hyderabad a laboratory and marketplace rather than a mass arsenal are compatible interpretation.<sup class='canon-note' data-provenance='e'>[e]</sup> No comparative production ranking among the Indian states is directly established.</p><!-- altwwii-writer-block:end -->"}
    ],
    related:[{href:"hyderabad.html",kicker:"Princely state",label:"Hyderabad"},{href:"indian-armored-design-genealogies.html",kicker:"Heavy branch",label:"Indian Armored Design Genealogies"},{href:"industrial-asylum.html",kicker:"Recruitment system",label:"Industrial Asylum"},{href:"chartered-restoration-territories.html",kicker:"Later corporate reach",label:"Chartered Restoration Territories"}],
    facts:[["State","Hyderabad"],["Established military base","Substantial princely guard force"],["Established early external supply","German aircraft and other military imports"],["Established commercial activity","Resale of some imported aircraft"],["Established later relationship","Japanese equipment and investment in the mid-1980s"],["Kotin–Kirov, Uralmash, and Yakovlev lineages","Working reconstruction"],["Prototype, repair, and short-run manufacture","Working extrapolation"],["Firms, products, contracts, and totals","Open"]]
  }),

  "russian-technical-communities-india":indianIndustryArticle({
    title:"Russian technical communities in India",eyebrow:"Industrial diaspora society · 1950s onward",infoboxKicker:"Émigré arsenal and university communities",flag:diasporaDiagram,
    lead:"<!-- altwwii-writer-block:start id=wb-g-20260816-r6t8a writer=g kind=revision created=2026-08-16T02:35:00-06:00 -->Former Soviet researchers, designers, engineers, firms, and projects first retreat into Russian successor states and then divide among several Indian successor states that invite them as industrial claimants.<sup class='canon-note' data-provenance='a'>[a]</sup> Their formation of enduring family communities around arsenals, plants, schools, universities, and princely workshops is incorporated social reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260816-r6t8b writer=g kind=revision created=2026-08-16T02:35:00-06:00 -->Migration of Soviet military-industrial personnel into several Indian states, their non-uniform division among hosts, and the conversion of Soviet-associated design paths into Indian systems are established.<sup class='canon-note' data-provenance='a'>[a]</sup> Institution-centered settlements, accompanying families, bilingual shops, local second generations, intermarriage, citizenship variation, surveillance, continuing Russian lineage names, population totals, neighborhoods, religious institutions, and family histories are extrapolated or open.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"formation",title:"Working communities built around work",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-r6t8c writer=g kind=revision created=2026-08-16T02:35:00-06:00 --><p>The author establishes invited industrial claimants, researchers, designers, and engineers, but does not describe their settlement form.<sup class='canon-note' data-provenance='a'>[a]</sup> Housing, clinics, schools, ration access, and security attached to arsenal or bureau contracts are compatible social extrapolation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"geography",title:"Distributed hosts",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-r6t8d writer=g kind=revision created=2026-08-16T02:35:00-06:00 --><p>Russian personnel divide among different Indian successor states rather than concentrating uniformly in Congress India or Hindustan; some may also enter princely states.<sup class='canon-note' data-provenance='a'>[a]</sup> Concentrations at specified ordnance centers, aircraft and radar plants, Hyderabad workshops, Pakistani depots, universities, proving grounds, or princely compounds are incorporated geography.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"language",title:"Working bilingual shops",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-r6t8e writer=g kind=revision created=2026-08-16T02:35:00-06:00 --><p>Russian-language design and teaching through translators, manuals pairing Cyrillic with English and local scripts, and a specialized Russian vocabulary among Indian apprentices are plausible consequences of migration.<sup class='canon-note' data-provenance='e'>[e]</sup> No language practice is directly established.</p><!-- altwwii-writer-block:end -->"},
      {id:"family",title:"Working family protection",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-r6t8f writer=g kind=revision created=2026-08-16T02:35:00-06:00 --><p>Contracts covering spouses, children, housing, food, and guarded transport would plausibly turn technical recruitment into family migration.<sup class='canon-note' data-provenance='e'>[e]</sup> The transcript does not establish accompanying families or contractual protections.</p><!-- altwwii-writer-block:end -->"},
      {id:"citizenship",title:"Working legal status",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-r6t8g writer=g kind=revision created=2026-08-16T02:35:00-06:00 --><p>Retention of Russian successor-state nationality, entry into host citizenship, protected-employee status, and differences between parents and children are compatible possibilities.<sup class='canon-note' data-provenance='e'>[e]</sup> No Indian host's citizenship or military-employment rules for these migrants are directly established.</p><!-- altwwii-writer-block:end -->"},
      {id:"generation",title:"Working Indian second generation",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-r6t8h writer=g kind=revision created=2026-08-16T02:35:00-06:00 --><p>Locally educated children entering Indian armed forces and firms, acquiring local languages, intermarrying, and understanding Russia through family memory form a compatible generational trajectory.<sup class='canon-note' data-provenance='e'>[e]</sup> Locations, schools, family patterns, and attitudes remain open.</p><!-- altwwii-writer-block:end -->"},
      {id:"politics",title:"Working politics of expertise",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-r6t8i writer=g kind=revision created=2026-08-16T02:35:00-06:00 --><p>Host surveillance, successor-state nationality claims, protected housing and salaries, and resentment of inherited lineage authority are compatible tensions around foreign military specialists.<sup class='canon-note' data-provenance='e'>[e]</sup> None is directly described in the canon transcript.</p><!-- altwwii-writer-block:end -->"},
      {id:"legacy",title:"Indian systems with Russian ancestry",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-r6t8j writer=g kind=revision created=2026-08-16T02:35:00-06:00 --><p>Designs associated in real history with Soviet postwar development become Indian systems because relevant personnel move south and divide among Indian hosts.<sup class='canon-note' data-provenance='a'>[a]</sup> Russian founder names persisting on overwhelmingly Indian institutions by the 1970s are compatible institutional development.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"}
    ],
    related:[{href:"soviet-military-industrial-diaspora.html",kicker:"Founding migration",label:"Soviet Military-Industrial Diaspora"},{href:"industrial-asylum.html",kicker:"Legal and economic basis",label:"Industrial Asylum"},{href:"paired-design-bureau-system.html",kicker:"Workplace institution",label:"Paired Design-Bureau System"},{href:"india-successors.html",kicker:"Host region",label:"Indian Successor States"}],
    facts:[["Established migration","Former Soviet personnel move through Russian successors into India"],["Established distribution","Several Indian national and possible princely hosts"],["Established technical result","Soviet-associated designs become competing Indian systems"],["Settlement type and family migration","Working reconstruction"],["Language and education","Open"],["Citizenship and legal status","Open"],["Community politics and intermarriage","Open"],["Population totals, sites, and institutions","Open"]]
  })
});
